/**
 * Deposit-attestation verification (Riddler #353).
 *
 * The expected messages, signatures and signer in
 * `test/vectors/deposit_attestation.json` are GENERATED BY THE SERVER
 * (`mix run scripts/generate_deposit_attestation_vectors.exs`), which is the only
 * side that produces attestations. They are never recomputed here.
 *
 * That direction is the whole point. This SDK only verifies, so a test that
 * derived its expectation from `buildDepositAttestationMessage` would pass for
 * any encoding -- including one that disagrees with the server on every real
 * quote. The failure would then surface as a client refusing legitimate deposit
 * addresses, or accepting one the server never signed, which is the attack #353
 * exists to stop.
 */

import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import {
  buildDepositAttestationMessage,
  recoverDepositAttestationSigner,
  verifyDepositAttestation,
  depositAttestationFields,
  DepositAttestationError,
  DEPOSIT_ATTESTATION_VERSION,
  type DepositAttestationFields,
} from "@xochi/signer";
import { CONFIG, isTronChain } from "../src/config";

const here = dirname(fileURLToPath(import.meta.url));
const fixture = JSON.parse(
  readFileSync(join(here, "vectors", "deposit_attestation.json"), "utf-8"),
) as {
  version: string;
  signer: string;
  /** Marks `signer` as the vectors' test key rather than any deploy's pin. */
  signer_is_test_key: boolean;
  signer_note: string;
  vectors: Array<{
    name: string;
    note: string;
    quote: DepositAttestationFields;
    message: string;
    deposit_attestation: string;
  }>;
};

describe("deposit attestation vectors (generated by the server)", () => {
  it("marks its signer as a TEST key, not the production pin", () => {
    // The artifact's `signer` is the all-abandon BIP-39 signer for these vectors.
    // The production pin is `capabilities.deposit_attestation_signer`, a different
    // value with a different job. Pinned here because the recovery assertions
    // below compare against `fixture.signer`, which is correct for verifying the
    // VECTORS and would be catastrophic for verifying live quotes -- it would
    // refuse every real one. If the producer ever drops this marker, that is a
    // change worth noticing rather than absorbing.
    expect(fixture.signer_is_test_key).toBe(true);
    // Only the flag is asserted. `signer_note` is prose: pinning its wording
    // would redden this repo's build over a producer-side reword that changes
    // no protocol, and the flag already carries the meaning.
  });

  it("the fixture actually has vectors", () => {
    // Guards the failure mode where every it.each below silently runs zero times.
    expect(fixture.vectors.length).toBeGreaterThanOrEqual(5);
    expect(fixture.signer).toMatch(/^0x[0-9a-f]{40}$/);
    expect(fixture.version).toBe(DEPOSIT_ATTESTATION_VERSION);
  });

  it.each(fixture.vectors.map((v) => [v.name, v] as const))(
    "%s: rebuilds the server's message byte-exactly",
    (_name, vector) => {
      expect(buildDepositAttestationMessage(vector.quote)).toBe(vector.message);
    },
  );

  it.each(fixture.vectors.map((v) => [v.name, v] as const))(
    "%s: recovers to the published signer",
    (_name, vector) => {
      expect(recoverDepositAttestationSigner(vector.quote, vector.deposit_attestation)).toBe(
        fixture.signer,
      );
    },
  );

  it.each(fixture.vectors.map((v) => [v.name, v] as const))(
    "%s: verifies fail-closed against the pinned signer",
    (_name, vector) => {
      expect(() =>
        verifyDepositAttestation(vector.quote, vector.deposit_attestation, fixture.signer),
      ).not.toThrow();
    },
  );
});

describe("independent cross-check (Riddler #798 signature_conformance.json)", () => {
  // Everything above shares one provenance: vectors generated by the script that
  // ships alongside this feature. If that generator and this verifier were both
  // wrong in the same way, nothing above would notice.
  //
  // This vector does not share that provenance. It was generated months earlier
  // by Riddler's `generate_signature_vectors.exs` for the #798 signing-seam
  // refactor, for an unrelated purpose, and is committed in a different file. It
  // is reproduced inline rather than vendored precisely so it cannot be
  // regenerated alongside ours -- if this ever needs updating, that is a signal
  // worth stopping on, not a copy to refresh.
  //
  // It also covers the case our own vectors did not until this was found: a
  // deposit address that is 0x-hex rather than base58. Deposit routes are not
  // Tron-only -- `OriginPull.deposit_address_for_vm/4` falls back to the solver's
  // own address for a non-TVM origin.
  //
  // Updated twice, for the v1 -> v2 field-set change (Riddler #846) and the
  // v2 -> v3 one (#870). That is the "stop and think" this vector exists to
  // force, and both were deliberate wire changes rather than drift: the
  // server-side entry was patched in place each time, leaving every other vector
  // in signature_conformance.json byte-identical, so this still has a provenance
  // our own generator cannot reach. The values below are transcribed from that
  // entry, never recomputed here -- recomputing would make it agree with us by
  // construction and destroy the only thing it is for.
  //
  // It is the STEALTH case, so the two optional fields are populated here -- our
  // own vectors would otherwise be the only thing distinguishing "encoded as an
  // empty line" from "omitted entirely".
  const fields: DepositAttestationFields = {
    intent_id: "intent-vector-0001",
    quote_id: "quote-vector-0001",
    wallet: "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
    from_chain_id: 8453,
    from_token: "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913",
    from_amount: "1000000",
    deposit_address: "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
    deposit_deadline: 1750000000,
    refund_address: "0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC",
    to_chain_id: 1,
    to_token: "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48",
    to_amount: "997000",
    min_to_amount: "992015",
    recipient: "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
    stealth_spending_pub_key: "0x02abababababababababababababababababababababababababababababababab",
    stealth_viewing_pub_key: "0x03cdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcd",
    settlement_preference: "stealth",
  };
  const message =
    "xochi-deposit-attestation:v3\n" +
    "intent-vector-0001\n" +
    "quote-vector-0001\n" +
    "0x70997970c51812dc3a010c7d01b50e0d17dc79c8\n" +
    "8453\n" +
    "0x833589fcd6edb6e08f4c7c32d4f71b54bda02913\n" +
    "1000000\n" +
    "0x70997970c51812dc3a010c7d01b50e0d17dc79c8\n" +
    "1750000000\n" +
    "0x3c44cdddb6a900fa2b585dd299e03d12fa4293bc\n" +
    "1\n" +
    "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48\n" +
    "997000\n" +
    "992015\n" +
    "0x70997970c51812dc3a010c7d01b50e0d17dc79c8\n" +
    "0x02abababababababababababababababababababababababababababababababab\n" +
    "0x03cdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcd\n" +
    "stealth";
  const signature =
    "0x37337d2b1d3d80a60d7ef7203c9974e555d6b339d9646344f120acc545cca5c6" +
    "587008302d4d6801a9c28c0ed88b46d4050cb0af3ad382392d0a48d0e433e9f71c";

  it("rebuilds a message generated by unrelated code, months earlier", () => {
    expect(buildDepositAttestationMessage(fields)).toBe(message);
  });

  it("recovers to the same signer our own vectors do", () => {
    // Both vector sets derive from the same all-abandon test mnemonic at the same
    // reserved index, so agreement here means the two independently generated
    // sets describe one signer -- not two implementations that merely agree with
    // themselves.
    expect(recoverDepositAttestationSigner(fields, signature)).toBe(fixture.signer);
  });

  it("verifies fail-closed against the pinned signer", () => {
    expect(() => verifyDepositAttestation(fields, signature, fixture.signer)).not.toThrow();
  });

  it("lowercases a 0x deposit address, not just a 0x token", () => {
    expect(buildDepositAttestationMessage(fields)).toContain(
      "0x70997970c51812dc3a010c7d01b50e0d17dc79c8",
    );
    expect(buildDepositAttestationMessage(fields)).not.toContain(
      "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
    );
  });
});

describe("encoding rules", () => {
  const base58 = fixture.vectors.find((v) => v.name === "tron_usdt_base58_verbatim")!;
  const mixed = fixture.vectors.find((v) => v.name === "evm_token_is_lowercased")!;

  it("keeps base58 T-addresses verbatim -- they are case-sensitive", () => {
    const message = buildDepositAttestationMessage(base58.quote);
    expect(message).toContain("TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t");
    expect(message).toContain("TJYeasTPa6gpEEfYGfp5LQjWXmdZQBpLzX");
  });

  it("lowercases a 0x token while leaving the base58 address in the same message alone", () => {
    const message = buildDepositAttestationMessage(mixed.quote);
    expect(message).toContain("0xabcdef0000000000000000000000000000000001");
    expect(message).not.toContain("0xAbCdEf0000000000000000000000000000000001");
    expect(message).toContain("TJYeasTPa6gpEEfYGfp5LQjWXmdZQBpLzX");
  });

  it("case-folding a T-address changes the recovered signer", () => {
    // Riddler #826 shipped exactly this bug on a read path. If a verifier
    // normalised base58 the way it normalises EVM hex, every real Tron quote
    // would fail to verify.
    const folded = {
      ...base58.quote,
      deposit_address: base58.quote.deposit_address.toLowerCase(),
    };
    expect(recoverDepositAttestationSigner(folded, base58.deposit_attestation)).not.toBe(
      fixture.signer,
    );
  });

  it("builds exactly 18 newline-joined lines with no trailing newline", () => {
    const message = buildDepositAttestationMessage(base58.quote);
    expect(message.split("\n")).toHaveLength(18);
    expect(message.endsWith("\n")).toBe(false);
  });

  it("encodes an absent stealth key as an empty line, not an omitted one", () => {
    // base58.quote is a public route, so both stealth fields are null. Dropping
    // the lines would shift settlement_preference up and sign a different deal.
    expect(base58.quote.stealth_spending_pub_key).toBeNull();
    const lines = buildDepositAttestationMessage(base58.quote).split("\n");
    expect(lines[15]).toBe("");
    expect(lines[16]).toBe("");
    expect(lines[17]).toBe("public");
  });

  it("encodes an absent refund_address as an empty line at index 9", () => {
    // The v3 field, and the one whose position matters most: it sits between
    // deposit_deadline and to_chain_id, so getting it wrong shifts the entire
    // destination side up by one and signs a different deal that still parses.
    expect(base58.quote.refund_address).toBeNull();
    const lines = buildDepositAttestationMessage(base58.quote).split("\n");
    expect(lines[9]).toBe("");
    expect(lines[10]).toBe(String(base58.quote.to_chain_id));
  });

  it("never ends on an optional field, so trimming cannot diverge", () => {
    // settlement_preference is last precisely so a public-route message -- the
    // common case -- does not end in "\n\n". A client that trimmed before
    // hashing would otherwise fail every public quote and pass stealth ones.
    for (const v of fixture.vectors) {
      expect(v.message.endsWith("\n")).toBe(false);
      expect(v.message.trimEnd()).toBe(v.message);
    }
  });

  it("keeps a base58 recipient verbatim on a Tron-destination route", () => {
    // The v2 half of the #826 hazard: recipient decides where the payout lands,
    // and folding a T-address yields a different, still-plausible address.
    const toTron = fixture.vectors.find((v) => v.name === "base58_recipient_case_preserved")!;
    expect(toTron.quote.recipient).toBe("TJYeasTPa6gpEEfYGfp5LQjWXmdZQBpLzX");
    const message = buildDepositAttestationMessage(toTron.quote);
    expect(message).toContain("TJYeasTPa6gpEEfYGfp5LQjWXmdZQBpLzX");
    expect(message).not.toContain("TJYeasTPa6gpEEfYGfp5LQjWXmdZQBpLzX".toLowerCase());
  });

  it("folding a base58 recipient changes the recovered signer", () => {
    const toTron = fixture.vectors.find((v) => v.name === "base58_recipient_case_preserved")!;
    const folded = { ...toTron.quote, recipient: toTron.quote.recipient.toLowerCase() };
    expect(recoverDepositAttestationSigner(folded, toTron.deposit_attestation)).not.toBe(
      fixture.signer,
    );
  });
});

describe("the v2 fields each bind independently (Riddler #846)", () => {
  // The attack is a whole-response swap for a quote the attacker legitimately
  // holds. Each field below is a dimension along which that quote could still
  // differ from what the victim asked for, so each must move the digest.
  const vector = fixture.vectors.find((v) => v.name === "stealth_meta_address_attested")!;

  const tampering: Array<[keyof DepositAttestationFields, unknown, string]> = [
    ["recipient", "0x000000000000000000000000000000000000dead", "redirects a public payout"],
    [
      "stealth_spending_pub_key",
      "0x02" + "ef".repeat(32),
      "redirects a stealth payout the victim cannot see",
    ],
    ["stealth_viewing_pub_key", "0x03" + "ef".repeat(32), "redirects a stealth payout"],
    ["to_chain_id", 42161, "pays out on a chain the recipient may not control"],
    ["to_token", "0x000000000000000000000000000000000000beef", "pays out in a worthless asset"],
    ["to_amount", "1", "misreports the payout promised"],
    ["min_to_amount", "1", "misreports the enforced floor"],
    ["wallet", "0x000000000000000000000000000000000000dead", "names a different requester"],
    ["deposit_deadline", 1760000000, "misreports how long the deposit is honoured"],
    ["settlement_preference", "public", "presents a stealth route as a public one"],
  ];

  it.each(tampering)("%s is bound -- tampering %s", (field, tampered) => {
    const swapped = { ...vector.quote, [field]: tampered } as DepositAttestationFields;
    expect(recoverDepositAttestationSigner(swapped, vector.deposit_attestation)).not.toBe(
      fixture.signer,
    );
  });
});

describe("newline injection", () => {
  // \n is the field delimiter and nothing escapes it, so a value containing one
  // moves a boundary rather than sitting inside a field. v1 signed only
  // server-generated ids and addresses; v2 signs caller-supplied wallet and
  // recipient, and the server's request validation does NOT stop a trailing
  // newline (base58?/1 trims before matching). Both sides refuse.
  const vector = fixture.vectors[0]!;

  it("refuses a trailing newline in recipient rather than signing around it", () => {
    const injected = { ...vector.quote, recipient: `${vector.quote.recipient}\n` };
    expect(() => buildDepositAttestationMessage(injected)).toThrow(/recipient contains a newline/);
  });

  it("refuses an embedded newline in wallet", () => {
    const injected = { ...vector.quote, wallet: "0xdead\n0xbeef" };
    expect(() => buildDepositAttestationMessage(injected)).toThrow(/wallet contains a newline/);
  });

  it("names the offending field, not just the position", () => {
    const injected = { ...vector.quote, to_token: "0xdead\n0xbeef" };
    expect(() => buildDepositAttestationMessage(injected)).toThrow(/to_token contains a newline/);
  });
});

describe("verifyDepositAttestation is fail-closed", () => {
  const vector = fixture.vectors[0]!;

  it("rejects a tampered deposit address -- the attack #353 exists to stop", () => {
    const tampered = { ...vector.quote, deposit_address: "TJYeasTPa6gpEEfYGfp5LQjWXmdZQBpLzY" };
    expect(() =>
      verifyDepositAttestation(tampered, vector.deposit_attestation, fixture.signer),
    ).toThrow(DepositAttestationError);
  });

  it("rejects a tampered amount", () => {
    const tampered = { ...vector.quote, from_amount: "999999999" };
    expect(() =>
      verifyDepositAttestation(tampered, vector.deposit_attestation, fixture.signer),
    ).toThrow(DepositAttestationError);
  });

  it("rejects an attestation from the wrong signer", () => {
    expect(() =>
      verifyDepositAttestation(
        vector.quote,
        vector.deposit_attestation,
        "0x0000000000000000000000000000000000000001",
      ),
    ).toThrow(/recovered to .* expected/);
  });

  it("throws when the attestation is missing rather than skipping the check", () => {
    // A missing attestation is exactly what an attacker can produce, so absence
    // must never be a reason to proceed.
    expect(() => verifyDepositAttestation(vector.quote, null, fixture.signer)).toThrow(
      /no deposit_attestation/,
    );
    expect(() => verifyDepositAttestation(vector.quote, undefined, fixture.signer)).toThrow(
      DepositAttestationError,
    );
  });

  it("throws when there is no pinned signer to compare against", () => {
    expect(() => verifyDepositAttestation(vector.quote, vector.deposit_attestation, null)).toThrow(
      /no deposit_attestation_signer/,
    );
  });

  it("throws on a malformed signature rather than surfacing an ethers error", () => {
    expect(() => verifyDepositAttestation(vector.quote, "0xdeadbeef", fixture.signer)).toThrow(
      DepositAttestationError,
    );
  });

  it("accepts a differently-cased pinned signer", () => {
    expect(() =>
      verifyDepositAttestation(
        vector.quote,
        vector.deposit_attestation,
        fixture.signer.toUpperCase().replace("0X", "0x"),
      ),
    ).not.toThrow();
  });
});

describe("depositAttestationFields", () => {
  // Only the server-chosen half lives in the quote. POST /xochi/quote does not
  // echo the request: its response has no wallet, no from_token, no to_token and
  // no stealth keys, and the chain ids only inside `route`. See the function's
  // own doc comment -- the caller-supplied half comes from params, which is also
  // what binds the attestation to this caller.
  const serverQuote = {
    intent_id: "xi_1",
    quote_id: "xq_1",
    from_amount: "5",
    deposit_address: "TJYeasTPa6gpEEfYGfp5LQjWXmdZQBpLzX",
    deposit_deadline: 1750000000,
    to_amount: "4",
    min_to_amount: "3",
  };
  const params = {
    wallet: "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
    from_chain_id: 728126428,
    from_token: "TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t",
    to_chain_id: 8453,
    to_token: "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913",
    from_amount: "5",
  } as any;

  it("reads snake_case and camelCase alike, on both sides", () => {
    const camel = depositAttestationFields(
      {
        intentId: "xi_1",
        quoteId: "xq_1",
        fromAmount: "5",
        depositAddress: "TJYeasTPa6gpEEfYGfp5LQjWXmdZQBpLzX",
        depositDeadline: 1750000000,
        toAmount: "4",
        minToAmount: "3",
      },
      {
        wallet: "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
        fromChainId: 728126428,
        fromToken: "TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t",
        toChainId: 8453,
        toToken: "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913",
        fromAmount: "5",
      } as any,
    );
    expect(camel).toEqual(depositAttestationFields(serverQuote, params));
  });

  it("stringifies a numeric from_amount without grouping or exponent", () => {
    const fields = depositAttestationFields({ ...serverQuote, from_amount: 1000000 }, params);
    expect(fields.from_amount).toBe("1000000");
  });

  it("defaults recipient to wallet, the way the server resolves it", () => {
    // put_default_recipient/1 server-side. Attesting the resolved value means one
    // deal has one encoding rather than two depending on whether the caller sent
    // the field.
    expect(depositAttestationFields(serverQuote, params).recipient).toBe(params.wallet);
    const explicit = { ...params, recipient_address: "0x1111111111111111111111111111111111111111" };
    expect(depositAttestationFields(serverQuote, explicit).recipient).toBe(
      explicit.recipient_address,
    );
  });

  it("defaults settlement_preference to public and nulls absent stealth keys", () => {
    const fields = depositAttestationFields(serverQuote, params);
    expect(fields.settlement_preference).toBe("public");
    expect(fields.stealth_spending_pub_key).toBeNull();
    expect(fields.stealth_viewing_pub_key).toBeNull();
  });

  it("nulls an absent deposit_deadline rather than coercing it to 0", () => {
    // Number(undefined) is NaN and Number(null) is 0; either would sign a
    // deadline the server never issued.
    const { deposit_deadline: _dropped, ...noDeadline } = serverQuote;
    expect(depositAttestationFields(noDeadline, params).deposit_deadline).toBeNull();
  });
});

describe("Tron chain config", () => {
  it("has a mainnet entry with both collectible TRC-20s", () => {
    const tron = CONFIG.CHAINS.tron!;
    expect(tron.chainId).toBe(728126428);
    expect(tron.isTron).toBe(true);
    expect(tron.isTestnet).toBe(false);
    // Server TokenRegistry, chain 728126428.
    expect(tron.usdc).toBe("TEkxiTehnzSmSe2XqrBj4w32RUN966rdz8");
    expect(tron.usdt).toBe("TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t");
  });

  it("exposes no EVM rpc for any Tron chain -- there is no client signing here", () => {
    // Every Tron chain in the table, derived rather than listed: the removed
    // Shasta/Nile entries are why a hardcoded list went stale here.
    const tronKeys = Object.keys(CONFIG.CHAINS).filter((key) => isTronChain(key));
    expect(tronKeys).toEqual(["tron"]);
    for (const key of tronKeys) {
      expect(CONFIG.CHAINS[key]!.rpc).toBeNull();
    }
  });

  it("keeps mainnet TRC-20 addresses in canonical base58 case", () => {
    const tron = CONFIG.CHAINS.tron!;
    for (const addr of [tron.usdc, tron.usdt]) {
      expect(addr).toMatch(/^T[1-9A-HJ-NP-Za-km-z]{33}$/);
      expect(addr).not.toBe(addr!.toLowerCase());
    }
  });
});
